-- 线性表进阶：单链表就地逆置的三指针过程。
INSERT INTO knowledge_point (name,description,course_id,parent_id,content_key,content_source,content_version,content_review_status,sort_order,deleted)
SELECT '单链表逆置','使用 prev、cur、next 三个指针逐结点反转 next，时间 O(n)、额外空间 O(1)。',course.id,parent.id,'cs408-linked-list-reversal','AISTU',1,'REVIEWED',8,0 FROM course JOIN knowledge_point parent ON parent.course_id=course.id AND parent.content_key='408-linear-lists' LEFT JOIN knowledge_point existing ON existing.content_key='cs408-linked-list-reversal' WHERE course.content_key='cs408-data-structures' AND existing.id IS NULL;
INSERT INTO tutor_content (knowledge_point_id,content_key,content_version,review_status,title,lesson_json,check_json)
SELECT point.id,'cs408-linked-list-reversal',1,'REVIEWED','单链表逆置',JSON_OBJECT('summary','单链表就地逆置使用 prev、cur、next 三个指针：先保存 cur.next，再让 cur.next 指向 prev，最后同时推进 prev 与 cur。循环结束后 prev 就是新表头，时间 O(n)、额外空间 O(1)。','steps',JSON_ARRAY('prev 初始化为 null，cur 指向原表头','先保存 next=cur.next，避免后继入口丢失','令 cur.next=prev，反转当前一条边','prev=cur、cur=next，直到 cur 为 null'),'visualization',JSON_OBJECT('kind','LINKED_LIST_REVERSAL','version',1,'elements',JSON_ARRAY('A','B','C','D')),'prerequisite',JSON_OBJECT('contentKey','cs408-singly-linked-list','title','单链表的结点与表示','description','先理解 next 指针与从表头遍历的含义。'),'nextStep',JSON_OBJECT('contentKey','cs408-linked-list-merge','title','有序链表归并','description','继续学习以尾指针稳定拼接两个有序链表。')),JSON_OBJECT('id','linked-list-reversal-v1','prompt','逆置循环中，在改写 cur.next 之前必须先做什么？','options',JSON_ARRAY(JSON_OBJECT('id','SAVE_NEXT','text','保存 next = cur.next'),JSON_OBJECT('id','MOVE_CUR','text','直接令 cur = cur.next')),'correctOptionId','SAVE_NEXT','correctExplanation','正确：先保存原后继，改写当前 next 后才能继续处理未逆置部分。','incorrectExplanation','不正确：若先移动或覆盖而未保存原后继，后续链路会丢失。') FROM knowledge_point point LEFT JOIN tutor_content existing ON existing.content_key='cs408-linked-list-reversal' AND existing.content_version=1 WHERE point.content_key='cs408-linked-list-reversal' AND existing.id IS NULL;
